 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function peek() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function consume() {
    return pos < tokens.length ? tokens[pos++] : null;
  }

  function expect(type) {
    const token = peek();
    if (!token || token.type !== type) {
      const inputLen = input.length;
      if (token) {
        throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
      } else {
        throw new ExprError(`unexpected end of input at ${inputLen}`, inputLen);
      }
    }
    return consume();
  }

  // Precedence levels
  const PRECEDENCE = {
    '+': 1,
    '-': 1,
    '*': 2,
    '/': 2,
    '%': 2,
    '^': 4,
  };

  // Check if an operator is right-associative
  function isRightAssociative(op) {\n    return op === '^';
  }

  // Parse primary expression: number, variable, unary +/-, parenthesized expr, or function call
  function parsePrimary() {
    const token = peek();

    if (!token) {
      throw new ExprError(`unexpected end of input at ${input.length}`, input.length);
    }

    // Unary operators: prefix + or -
    if (token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      const op = token.value;
      const opIndex = token.index;
      consume();
      const operand = parsePrimary();
      return {
        type: 'unary',
        op,
        operand,
        index: opIndex,
      };
    }

    // Numbers
    if (token.type === 'number') {
      consume();
      return {
        type: 'number',
        value: token.value,
        index: token.index,
      };
    }

    // Variables or function calls
    if (token.type === 'name') {
      const name = token.value;
      const nameIndex = token.index;
      consume();

      // Check for function call
      if (peek() && peek().type === 'lparen') {
        consume(); // consume (

        const args = [];

        // Parse arguments
        if (peek() && peek().type !== 'rparen') {
          args.push(parseExpression(0));

          while (peek() && peek().type === 'comma') {
            consume(); // consume comma
            args.push(parseExpression(0));
          }
        }

        expect('rparen');

        return {
          type: 'call',
          name,
          args,
          index: nameIndex,
        };
      }

      // Just a variable
      return {
        type: 'variable',
        name,
        index: nameIndex,
      };
    }

    // Parenthesized expression
    if (token.type === 'lparen') {
      consume();
      const expr = parseExpression(0);
      expect('rparen');
      return expr;
    }

    // Otherwise unexpected
    throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
  }

  // Precedence-climbing parser for binary operators
  function parseExpression(minPrecedence) {
    let left = parsePrimary();

    while (true) {
      const token = peek();

      // Not an operator or end of input
      if (!token || token.type !== 'operator') {
        break;
      }

      const op = token.value;
      if (!(op in PRECEDENCE)) {
        break;
      }

      const precedence = PRECEDENCE[op];
      if (precedence < minPrecedence) {
        break;
      }

      const opIndex = token.index;
      consume();

      // For right-associative operators, use the same precedence; for left, use precedence + 1
      const nextMinPrecedence = isRightAssociative(op) ? precedence : precedence + 1;
      const right = parseExpression(nextMinPrecedence);

      left = {
        type: 'binary',
        op,
        left,
        right,
        index: opIndex,
      };
