import { ExprError, tokenize } from './tokenize.js';

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  let pos = 0;

  function peek() {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function consume() {
    return pos < tokens.length ? tokens[pos++] : null;
  }

  function expect(type) {
    const token = peek();
    if (!token || token.type !== type) {
      const inputLen = input.length;
      if (token) {
        throw new ExprError(`unexpected token '${token.value}' at ${token.index}`, token.index);
      } else {
        throw new ExprError(`unexpected end of input at ${inputLen}`, inputLen);
      }
